const rows = $input.all();
return rows.map((item) => {
  const r = item.json || {};
  const total = Number(r.total_tokens || 0);
  const firstModel = Number(r.deepseek_model_total_tokens || 0);
  const secondModel = Number(r.deepseek_result_model_total_tokens || 0);
  return { json: { ...r, total_tokens_check: firstModel + secondModel, totals_match: total === firstModel + secondModel, report_scope: 'all recorded deepseek usage', generated_at: new Date().toISOString() } };
});

